/* eslint-disable space-in-parens */

import zeros = require( '@stdlib/ndarray/zeros' );
import scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
import Complex128 = require( '@stdlib/complex/float64/ctor' );
import zfillNaN = require( './index' );


// TESTS //

// The function returns an ndarray...
{
	const x = zeros( [ 10 ], {
		'dtype': 'complex128'
	});
	const alpha = scalar2ndarray( new Complex128( 0.0, 0.0 ), {
		'dtype': 'complex128'
	});
	const start = scalar2ndarray( 0, {
		'dtype': 'generic'
	});
	const end = scalar2ndarray( 10, {
		'dtype': 'generic'
	});

	zfillNaN( [ x, alpha, start, end ] ); // $ExpectType complex128ndarray
}

// The compiler throws an error if the function is provided a first argument which is not an array of ndarrays...
{
	zfillNaN( '10' ); // $ExpectError
	zfillNaN( 5 ); // $ExpectError
	zfillNaN( true ); // $ExpectError
	zfillNaN( false ); // $ExpectError
	zfillNaN( null ); // $ExpectError
	zfillNaN( undefined ); // $ExpectError
	zfillNaN( [] ); // $ExpectError
	zfillNaN( {} ); // $ExpectError
	zfillNaN( ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = zeros( [ 10 ], {
		'dtype': 'complex128'
	});
	const alpha = scalar2ndarray( new Complex128( 0.0, 0.0 ), {
		'dtype': 'complex128'
	});
	const start = scalar2ndarray( 0, {
		'dtype': 'generic'
	});
	const end = scalar2ndarray( 10, {
		'dtype': 'generic'
	});

	zfillNaN(); // $ExpectError
	zfillNaN( [ x, alpha, start, end ], {} ); // $ExpectError
}
